s=s.replace('postType:kind,anonymous,communityId:communityId||null,locationLabel:location,topics:topics.split(",").map(x=>x.trim()).filter(Boolean)}});if(file){const optimized=await optimizeAcademicImage(file,1920);const type=optimized.type.toLowerCase();const prepared=await prepareFn({data:{fileName:optimized.name,contentType:type,size:optimized.size,purpose:"posts"}});const {error}=await supabase.storage.from(prepared.bucket).uploadToSignedUrl(prepared.path,prepared.token,optimized,{contentType:type});if(error)throw error;await finalizeFn({data:{postId:post.id,path:prepared.path,altText:alt}})}return post','postType:kind,anonymous,communityId:communityId||null,locationLabel:location,topics:topics.split(",").map(x=>x.trim()).filter(Boolean),hasAttachment:Boolean(file)}});if(file){const uploadFile=file.type.startsWith("image/")?await optimizeAcademicImage(file,1920):file;const type=uploadFile.type.toLowerCase();const prepared=await prepareFn({data:{fileName:uploadFile.name||file.name,contentType:type,size:uploadFile.size,purpose:"posts"}});const {error}=await supabase.storage.from(prepared.bucket).uploadToSignedUrl(prepared.path,prepared.token,uploadFile,{contentType:type});if(error)throw error;await finalizeFn({data:{postId:post.id,path:prepared.path,altText:file.type==="application/pdf"?file.name:alt,fileName:file.name}})}return post')
s=s.replace('accept="image/jpeg,image/png,image/webp"','accept="image/jpeg,image/png,image/webp,application/pdf"')
